"""Complete Idun composed dishes with full cooking, mayonnaise and garnish methods."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

merges=[];updatedids=[]
def merge(n,r,reason):
 s=src(n);aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason=reason)
 if s['id'] not in r['sourceAliases']:r['sourceAliases'].append(s['id']);r['source']+=' Equivalent source retained: '+s['recipe']['source']
 records.pop(s['id'],None);merges.append(s)

def mayoitems(a=150,m=.25):
 return [yolks(2),salt(.5),cayenne(),I('mustard',m,'tsp','prepared Dijon mustard','Use the same amount of another smooth prepared mustard.'),oil(a),vinegar(15,'tarragon'),lemon(7.5),I('mayowater',15,'ml','freshly boiled drinking water for the mayonnaise','Use the same amount of warm drinking water for a gentler addition.')]
MAYO=['In a clean bowl set on a damp towel, whisk {{yolks}}, {{salt}}, {{cayenne}} and {{mustard}} until smooth.',
 'Measure {{oil}}, {{vinegar}} and {{lemon}} into separate small jugs. Whisk oil into the yolks a few drops at a time until thickened, then add the remaining oil in a thin stream, alternating small additions of the measured vinegar and lemon juice. Pause pouring whenever oil pools and whisk until it blends in.',
 'Gradually whisk {{mayowater}} into the thick sauce rather than pouring it all onto the yolks. Cover and refrigerate at 4°C (40°F) or colder while preparing the dish. The hot-water addition does not pasteurize the mayonnaise; commercially pasteurized yolks are specified.']
def eggitems():return [eggs(2),water(750,'eggwater')]
EGGPREP=['Place {{eggs}} in a saucepan with {{eggwater}}, topping up only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and leave for 12 minutes. Cool under cold running water and peel. The yolks and whites must be firm throughout; cut as directed when garnishing.']
def greens(a=200,sa=.25,so=15):
 return [I('lettuce',a,'g','crisp lettuce leaves, trimmed weight','Use the same weight of romaine or little-gem leaves.'),I('saladsalt',sa,'tsp','fine salt for the salad','Reduce or omit to taste.'),I('paprika',.25,'tsp','sweet paprika','Use the same amount of mild smoked paprika for a different flavor, or omit.'),I('saladoil',so,'ml','olive oil for the salad','Use the same volume of sunflower oil.'),I('saladvinegar',15,'ml','white wine vinegar for the salad','Use the same volume of cider vinegar.')]
GREENPREP='Wash {{lettuce}} in cold water, drain and dry thoroughly, then cut across into bite-size strips. Immediately before assembly, toss with {{saladsalt}}, {{paprika}}, {{saladoil}} and {{saladvinegar}}.'
def garnish(hearts=100,radish=False):
 a=[I('hearts',hearts,'g','small lettuce hearts, trimmed weight','Use the same weight of tender inner romaine leaves.'),I('capers',30,'ml','capers, drained','Use the same volume of finely chopped cornichons.'),I('olives',4,'','pitted green olives','Use the same number of pitted black olives.')]
 if radish:a.append(I('radishes',6,'','small radishes','Use the same number of thin cucumber rounds for a milder garnish.'))
 return a
def garnishstep(radish=False):return 'Wash and dry {{hearts}}'+(' and scrub {{radishes}}' if radish else '')+'. Drain {{capers}} and thinly slice {{olives}}'+(' and the radishes' if radish else '')+'. Cut the hard-boiled eggs into wedges. Arrange the lettuce hearts, egg wedges, capers, olive slices'+(' and radish slices' if radish else '')+' around the platter.'

lobsteritems=[I('lobsters',800,'g','whole raw lobsters, about two small lobsters, dispatched by the fishmonger','Use the complete prepared-lobster variation for cooked shellfish.'),water(4000,'poachwater'),I('poachsalt',150,'g','coarse salt for the lobster cooking water; most is discarded','Use the same weight of fine salt, or reduce for a less salty cooking liquid.')]+mayoitems(150,.5)+eggitems()+greens(300,so=30)+[I('cucumber',50,'g','fresh cucumber, approximately ten thin slices','Use the same weight of extra tomato.'),I('tomatoes',240,'g','ripe tomatoes, about two medium tomatoes','Use the same weight of cherry tomatoes, halved.')]
LOBSTER=['Bring {{poachwater}} and {{poachsalt}} to a boil in a pot large enough for {{lobsters}}. Carefully lower in the freshly dispatched lobsters, return to a gentle boil and cook for about 12–18 minutes for small whole lobsters; size and starting temperature affect the time. Check that the tail and claw meat is pearly white and opaque throughout before removing.',
 'Drain the lobsters and let them cool only until safe to handle. Split the bodies lengthwise, crack the claws and remove the tail and claw meat. Discard shell, stomach sac behind the eyes and the dark intestinal vein; check the meat carefully for shell fragments. Spread the meat in a shallow clean container, cover loosely and refrigerate promptly until cold, about 45–60 minutes. Do not leave it on the counter to cool completely.']
LOBSTERASSEMBLE=['Cut the cold lobster meat into bite-size pieces, reserving a few attractive pieces for the top. Arrange the rest in a low mound on a chilled platter, spoon over the mayonnaise and top with the reserved meat.',
 GREENPREP+' Wash and thinly slice {{cucumber}} and {{tomatoes}}, then fold into the dressed lettuce. Arrange the salad around the lobster and garnish with the hard-boiled eggs cut into slices.',END]
r=add(92,'Idun Lobster with Mayonnaise and Dressed Lettuce',6,110,'Chilled lobster is coated with homemade tarragon-lemon mayonnaise and surrounded by crisp lettuce, cucumber, tomatoes and sliced eggs.',lobsteritems,LOBSTER+EGGPREP+MAYO+LOBSTERASSEMBLE,
 'Original Idun recipe 174 and its duplicate extraction give two 400 g lobsters, 4 litres water and 150 g cooking salt. Most cooking salt is discarded with the water. The full referenced lobster preparation and mayonnaise without gelatin are supplied here. Three unspecified lettuce heads become 300 g trimmed leaves, two tomatoes 240 g, and ten cucumber slices 50 g. Cayenne is standardized to one-sixteenth teaspoon. Six small first-course portions follow the source, not six substantial main meals. Cooling time is included. The original canned alternative is specified only as a one-litre can including packing liquid; its drained yield is unknown. The full prepared-lobster variation uses a chosen 240 g drained meat portion for convenience, not a claimed conversion of that can.');finish(r);r['category']='Starters'
vi=[i for i in copy.deepcopy(lobsteritems) if i['key'] not in ['lobsters','poachwater','poachsalt']]+[I('cookedlobster',240,'g','cooked lobster meat, chilled and drained weight','Use the same weight of cooked peeled prawns for a different shellfish version.')]
variant(r,'prepared-lobster','With prepared cooked lobster',vi,['Drain {{cookedlobster}} well and check carefully for shell fragments. Keep covered in the refrigerator until assembly.']+EGGPREP+MAYO+LOBSTERASSEMBLE)
merge(93,r,'Same full Idun No174 lobster formula, separate dressed salad and gelatin-free mayonnaise; duplicate extraction of the same printed recipe, with prepared-lobster option retained.')

chickenitems=[I('chicken',1000,'g','small whole chicken, oven-ready and eviscerated, cut into joints by the butcher','Use the complete cooked-chicken variation when using leftovers.'),water(1200,'poachwater'),I('poachsalt',1,'tbsp','fine salt for the chicken cooking liquid','Reduce to taste; most remains in the discarded cooking liquid.'),I('peppercorns',4,'','white peppercorns','Use the same number of black peppercorns.'),I('bay',1,'','dried bay leaf','Use one fresh bay leaf, or omit.')]+mayoitems()+eggitems()+greens()+garnish()
CHICKEN=['Put {{poachwater}}, {{poachsalt}}, {{peppercorns}} and {{bay}} in a snug saucepan and bring to a simmer. Add {{chicken}}; add only enough extra hot water to cover the joints. Do not wash raw chicken. Cover partially and simmer gently for about 45–70 minutes, skimming foam if needed, until the thickest breast and thigh portions reach 74°C (165°F), checking away from bone. Older birds may take longer to become tender.',
 'Lift out the chicken. As soon as it is cool enough to handle, remove the skin and bones and cut the meat into even bite-size pieces. Spread in a shallow container and refrigerate promptly until cold, about 60 minutes. Do not leave it at room temperature to cool completely. Discard the cooking liquid or chill it separately for another use.']
CHICKENASSEMBLE=[GREENPREP+' Arrange the dressed lettuce on a chilled platter. Layer the cold chicken and mayonnaise into a low mound on top.',garnishstep(),END]
r=add(94,'Idun Chicken with Mayonnaise and Lettuce',6,160,'Gently poached chicken is layered with tarragon-lemon mayonnaise over dressed lettuce and finished with eggs, capers and olives.',chickenitems,CHICKEN+EGGPREP+MAYO+CHICKENASSEMBLE,
 'Original No180 offers either one young whole chicken or 300 g cooked leftovers. This base chooses a modern 1 kg prepared bird and uses all its cooked meat; the leftover version makes smaller portions and is supplied in full. The historical singeing with spirits and prolonged soaking are replaced with a butcher-prepared bird, hygienic handling and temperature-checked poaching. The source 1.2 litre water is retained as a starting quantity, with topping up only to cover the joints. The full salad from No176 and mayonnaise from No10 are supplied; no gelatin is listed for this dish and none is added. Two lettuce heads become 200 g trimmed leaves, two small garnish hearts 100 g. Six portions follow the source and vary in size between versions; the time includes chilling.');finish(r)
vi=[i for i in copy.deepcopy(chickenitems) if i['key'] not in ['chicken','poachwater','poachsalt','peppercorns','bay']]+[I('cookedchicken',300,'g','cooked boneless chicken, chilled','Use the same weight of cooked boneless turkey.')]
variant(r,'cooked-chicken','Source alternative — cooked chicken leftovers',vi,['Check {{cookedchicken}} for skin and bones and cut into even bite-size pieces. Use properly refrigerated cooked chicken; keep cold until assembly. This version makes six small starter portions and needs about 30 minutes if the chicken is already cold.']+EGGPREP+MAYO+CHICKENASSEMBLE)

tongueitems=[I('tongue',700,'g','raw calf tongue, trimmed by the butcher','Use a similar weight of veal tongue; a larger beef tongue needs longer simmering and thicker slices may need longer frying.'),water(2000,'poachwater'),I('poachsalt',1,'tbsp','fine salt for the tongue cooking water','Reduce to taste; most remains in the discarded cooking liquid.'),I('coategg',1,'','large egg for coating','Use one large pasteurized shell egg if preferred.'),I('cream',15,'ml','pouring cream','Use the same volume of whole milk.'),I('crumbs',40,'g','finely crushed plain rusks','Use the same weight of fine dry breadcrumbs.'),I('butter',60,'g','butter for frying','Use the same weight of clarified butter; omit additional frying salt.'),I('parsley',5,'g','fresh parsley sprigs','Use the same weight of small chervil sprigs.')]+mayoitems(200)
TONGUE=['Bring {{poachwater}} and {{poachsalt}} to a boil in a snug saucepan. Add {{tongue}}, reduce to a gentle simmer and cover partially; add hot water only as needed to keep the tongue covered. Simmer for about 2–3 hours, until a skewer enters easily and the thickest part is at least 71°C (160°F). Tenderness, not the clock alone, determines when it is ready.',
 'Lift out the tongue and let it cool just enough to handle. Peel away the tough outer skin while warm and trim away any hard gristle or fat at the root. Cut lengthwise into three slices and halve each to make six pieces at the base yield; when scaling, keep similar slice thickness.',
 'Whisk {{coategg}} with {{cream}} in a shallow dish. Spread {{crumbs}} on a plate. Dip each tongue slice into the egg mixture, let excess drip off, then coat both sides with the crumbs. Discard unused coating that has touched egg.',
 'Melt {{butter}} in a wide frying pan over medium heat. Fry the breaded slices for about 3–4 minutes per side until crisp, golden and hot through, lowering the heat if the butter browns too quickly. Work in batches with portions of the measured butter if the pan is crowded.',
 'Arrange on a warm platter, spoon the chilled mayonnaise beside the slices just before serving, and garnish with washed {{parsley}}. Serve promptly so the crumb coating stays crisp.',END]
r=add(95,'Idun Breaded Calf Tongue with Mayonnaise',6,220,'Tender simmered calf tongue is sliced, coated in fine rusks and fried in butter, then served with tarragon-lemon mayonnaise and parsley.',tongueitems,MAYO+TONGUE,
 'The two entries reproduce Idun No102. Its reference to No101 supplies preparation and boiling, not the separate Madeira-sauce braise in that preceding recipe. A complete simmer-until-tender and warm peeling method is supplied. One tongue is represented by a chosen 700 g raw trimmed weight; tenderness controls the time. Half a Swedish coffee cup of crushed rusks is represented by a chosen 40 g, not half a US cup. Three tablespoons butter use the source book’s convention of 60 g, explicitly printed in adjacent recipes. The missing parsley garnish is supplied at 5 g. Mayonnaise No10 is written out with the 200 ml oil and other quantities listed in No102, without adding unlisted gelatin. Six portions follow the source. Total time allows a slow tongue but can be shorter for a tender small tongue.');finish(r)
merge(96,r,'Same full Idun No102 tongue, breading, butter frying and 200ml-oil mayonnaise formula; duplicate source extraction, including missing parsley garnish restored in canonical95.')

salmonitems=[I('salmon',750,'g','raw salmon fillet, pin bones removed','Use the same weight of trout fillet; thickness determines cooking time.'),water(120,'fishwater')]+mayoitems()+eggitems()+greens()+garnish(150,True)
SALMON=['Heat the oven to 180°C (350°F). Put {{salmon}} skin-side down in a snug baking dish and pour {{fishwater}} around it. Cover the dish tightly with a lid or foil. Bake for about 18–25 minutes, depending on thickness, until the thickest part reaches 63°C (145°F).',
 'Lift the fish out of the cooking liquid. Once it is cool enough to handle, remove skin and any remaining bones, keeping the flesh in broad pieces. Place in a shallow container and refrigerate promptly until cold, about 60 minutes; do not leave it on the counter to cool completely.']
SALMONASSEMBLE=[GREENPREP+' Place the dressed lettuce on a chilled platter. Arrange broad slices or flakes of the cold salmon in a low mound on top and coat with the chilled mayonnaise.',garnishstep(True),END]
r=add(103,'Idun Salmon with Mayonnaise, Capers and Radishes',6,120,'Chilled salmon rests on dressed lettuce beneath tarragon-lemon mayonnaise, with eggs, capers, olives and crisp radishes around the platter.',salmonitems,SALMON+EGGPREP+MAYO+SALMONASSEMBLE,
 'Both entries reproduce Idun No176, which begins with 600 g cooked boneless salmon. This from-scratch version uses a chosen 750 g raw fillet to allow for skin and cooking losses, not a guaranteed conversion; use all the resulting flesh. The source’s 600 g cooked-fish alternative is retained in full. The oven-poaching method, water and timing are modern additions to make the recipe self-contained. Two lettuce heads become 200 g trimmed leaves and three small garnish hearts 150 g. The mayonnaise follows the listed quantities and explicitly omits gelatin as directed by the original. Six starter portions follow the source and the time includes chilling.');finish(r);r['category']='Starters'
vi=[i for i in copy.deepcopy(salmonitems) if i['key'] not in ['salmon','fishwater']]+[I('cookedsalmon',600,'g','cooked boneless salmon, chilled weight','Use the same weight of properly refrigerated cooked trout.')]
variant(r,'cooked-salmon','Source alternative — cooked salmon leftovers',vi,['Check {{cookedsalmon}} for skin and bones and divide into broad slices or flakes. Keep covered and refrigerated until assembly. This version takes about 30 minutes with already chilled fish.']+EGGPREP+MAYO+SALMONASSEMBLE)
merge(104,r,'Same full Idun No176 salmon, gelatin-free mayonnaise, dressed lettuce and egg/caper/olive/radish garnish; duplicate extraction with full cooked-leftover alternative retained.')

assert len(newids)==4 and len(merges)==3
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full Idun primary methods, measured cooking and mayonnaise components, garnishes and prepared alternatives','repair-batch-037.py'))
for s in merges:db.execute('insert or replace into decisions values(?,?,?,?,?)',(s['id'],s['bodySha256'],'prepared-merge',aliases[s['id']]['reason'],'repair-batch-037.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newAliases=len(merges),totalOverrides=len(records),totalAliases=len(aliases))))

